36	// ConflictForkPath computes the fork filename for saving conflicting local
37	// changes, suffixed with a short hash of the local content's plaintext hash.
38	// The suffix keeps every conflicting writer's fork distinct: with one fixed
39	// path per file, a later device's conflict would overwrite the conflict copy a
40	// previous device already committed, silently dropping that device's edit from
41	// the current tree. The plaintext hash (not the blob hash) is used because the
42	// encrypted envelope is non-deterministic across devices. The fixed-path
43	// result of ConflictLocalPath is returned when no plaintext hash is available.
44	// e.g. "ideas.md" -> "ideas.conflict-local-1a2b3c4d.md"
45	func ConflictForkPath(path string, local vault.TreeEntry) string {
46		base := ConflictLocalPath(path)
47		hash := local.PlaintextHash
48		if hash == "" {
49			return base
50		}
51		if len(hash) > 8 {
52			hash = hash[:8]
53		}
54		ext := filepath.Ext(base)
55		if ext != "" {
56			return strings.TrimSuffix(base, ext) + "-" + hash + ext
57		}
58		return base + "-" + hash
59	}
