97			baseEntry, inBase := base.Entries[path]
98			localEntry, inLocal := local.Entries[path]
99			remoteEntry, inRemote := remote.Entries[path]
100	
101			// 1. Unchanged anywhere
102			if inBase && inLocal && inRemote &&
103				baseEntry.PlaintextHash == localEntry.PlaintextHash &&
104				baseEntry.PlaintextHash == remoteEntry.PlaintextHash {
105				merged.Entries[path] = localEntry
106				continue
107			}
108	
109			// 2. Added only in Local
110			if !inBase && inLocal && !inRemote {
111				merged.Entries[path] = localEntry
112				continue
113			}
114	
115			// 3. Added only in Remote
116			if !inBase && !inLocal && inRemote {
117				merged.Entries[path] = remoteEntry
118				continue
119			}
120	
121			// 4. Deleted only in Local (unchanged in Remote)
122			if inBase && !inLocal && inRemote && baseEntry.PlaintextHash == remoteEntry.PlaintextHash {
123				// Deleted, omit from merged
124				continue
125			}
126	
127			// 5. Deleted only in Remote (unchanged in Local)
128			if inBase && inLocal && !inRemote && baseEntry.PlaintextHash == localEntry.PlaintextHash {
129				// Deleted, omit from merged
130				continue
131			}
132	
133			// 6. Modified only in Local (unchanged in Remote)
134			if inBase && inLocal && inRemote &&
135				baseEntry.PlaintextHash != localEntry.PlaintextHash &&
136				baseEntry.PlaintextHash == remoteEntry.PlaintextHash {
137				merged.Entries[path] = localEntry
138				continue
139			}
140	
141			// 7. Modified only in Remote (unchanged in Local)
142			if inBase && inLocal && inRemote &&
143				baseEntry.PlaintextHash == localEntry.PlaintextHash &&
144				baseEntry.PlaintextHash != remoteEntry.PlaintextHash {
145				merged.Entries[path] = remoteEntry
146				continue
147			}
148	
149			// 8. Both modified or added
150			if inLocal && inRemote {
151				if localEntry.PlaintextHash == remoteEntry.PlaintextHash {
152					// Both made identical change
153					merged.Entries[path] = localEntry
154					continue
155				}
156	
157				// Incompatible modification collision!
158				var basePtr *vault.TreeEntry
159				if inBase {
160					basePtr = &baseEntry
161				}
162				conflicts = append(conflicts, Conflict{
163					Path:        path,
164					BaseEntry:   basePtr,
165					LocalEntry:  localEntry,
166					RemoteEntry: remoteEntry,
167				})
168				// Place remote version in merged by default
169				merged.Entries[path] = remoteEntry
170				continue
171			}
172	
173			// 9. Deleted in one, modified in the other -> conflict
174			var basePtr *vault.TreeEntry
175			if inBase {
176				basePtr = &baseEntry
177			}
178			conflicts = append(conflicts, Conflict{
179				Path:        path,
180				BaseEntry:   basePtr,
181				LocalEntry:  localEntry,
182				RemoteEntry: remoteEntry,
183			})
