func (e *Engine) mergeBookkeeping(ctx context.Context, c Conflict, localPlain []byte) ([]byte, bool) {
	switch {
	case isLogFile(c.Path):
		remotePlain, err := e.fetchPlaintext(ctx, c.RemoteEntry.BlobHash)
		if err != nil {
			return nil, false
